updated AS (
  UPDATE public.logistica_noleggio t
  SET
    luogo_commessa = s.luogo_commessa,
    fornitore = s.fornitore,
    descrizione = s.descrizione,
    qta_mdo = s.qta_mdo,
    accessori_1 = s.accessori_1,
    qta_1 = s.qta_1,
    accessori_2 = s.accessori_2,
    qta_2 = s.qta_2,
    oda = s.oda,
    nolo_dal = s.nolo_dal,
    nolo_al = s.nolo_al,
    stato = s.stato,
    utilizzatore = s.utilizzatore,
    note = s.note,
    active = true,
    updated_at = now()
  FROM src s
  WHERE lower(coalesce(t.commessa, '')) = lower(coalesce(s.commessa, ''))
    and lower(coalesce(t.descrizione, '')) = lower(coalesce(s.descrizione, ''))
    and lower(coalesce(t.numero_contratto, '')) = lower(coalesce(s.numero_contratto, ''))
)
INSERT INTO public.logistica_noleggio(
  commessa,
  luogo_commessa,
  fornitore,
  descrizione,
  qta_mdo,
  accessori_1,
  qta_1,
  accessori_2,
  qta_2,
  numero_contratto,
  oda,
  nolo_dal,
  nolo_al,
  stato,
  utilizzatore,
  note,
  active
)
SELECT
  s.commessa,
  s.luogo_commessa,
  s.fornitore,
  s.descrizione,
  s.qta_mdo,
  s.accessori_1,
  s.qta_1,
  s.accessori_2,
  s.qta_2,
  s.numero_contratto,
  s.oda,
  s.nolo_dal,
  s.nolo_al,
  s.stato,
  s.utilizzatore,
  s.note,
  true
FROM src s
WHERE NOT EXISTS (
  SELECT 1
  FROM public.logistica_noleggio t
  WHERE lower(coalesce(t.commessa, '')) = lower(coalesce(s.commessa, ''))
    and lower(coalesce(t.descrizione, '')) = lower(coalesce(s.descrizione, ''))
    and lower(coalesce(t.numero_contratto, '')) = lower(coalesce(s.numero_contratto, ''))
);
